CREATE SET TABLE MDP01_META.META_ETL_DEPENDENCY ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      dependency_id INTEGER NOT NULL,      parent_job_id INTEGER NOT NULL,      child_job_id INTEGER NOT NULL,      dependency_type VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC,      condition_expression VARCHAR(1000) CHARACTER SET LATIN NOT CASESPECIFIC,      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( dependency_id )UNIQUE INDEX ( parent_job_id ,child_job_id );